33	const checkInterval = 24 * 60 * 60 * 1000;
34	const versionsUrl = 'https://storybook.js.org/versions.json';
35	
36	async function fetchLatestVersion(v: string) {
37	  const fromFetch = await fetch(`${versionsUrl}?current=${v}`);
38	  return fromFetch.json();
39	}
